import "./AboutUs.css";
import anh1 from "./images/anh1.jpeg"
const AboutUs = () => {
    return (
        <div className="about-us">
            <h1>Giới thiệu</h1>
            <p>
                Chào mừng đến với cửa hàng của chúng tôi! Chúng tôi cung cấp những sản phẩm thời trang chất lượng cao với giá cả phải chăng.
            </p>
            <h2>1.Lịch sử hình thành</h2>
            <p>
                Sato Store ra đời từ 2012, khởi đầu ở một cửa hàng nhỏ trên phố Lò Đúc. Adam Store những ngày đầu được gây dựng bởi 3 chàng trai trẻ tuổi, ôm trong mình hoài bão thay đổi xu hướng thời trang Việt Nam.
                Bằng đam mê với vest và bằng những cố gắng bền bỉ trong từng giây phút, Adam Store đã tiên phong trong ngành thời trang, thay đổi tư duy khách hàng, trở thành thương hiệu Việt Nam lớn nhất trong thị phần vest may sẵn, là thương hiệu uy tín về đồ Âu cho nam giới.
            </p>
            <img src={anh1} alt="Fashion Store" className="about-image" />
            <h2>5 lý do khách hàng nên mua sản phẩm của Adam Store</h2>
            <p>
                Trở thành thương hiệu thời trang hàng đầu, được yêu thích bởi mọi khách hàng.
            </p>

        </div>
    );
};

export default AboutUs;
